        feat['vzo_14'] = _vzo
        feat['vzo_cross_dn_40'] = ((_vzo < 40) & (_vzo.shift(1) >= 40)).astype(float)
        feat['vzo_negative'] = (_vzo < 0).astype(float)

        # ── 41) 고가권/저가권 거래량비 (20) — 분산(distribution) 감지 ──
        _pos20 = (cl - _don_lo) / _don_w
